makeMtLab(document.getElementById("lab-l19"),{id:"l19",scenarios:[{"label": "Ví dụ: Năng lực tuần", "note": "Giờ kế hoạch × năng lực giờ.", "steps": [{"t": "90 giờ × 1 800 hộp/giờ", "html": "<p class=\"mt-calc\">= 162 000 hộp lý thuyết<\/p>"}, {"t": "Nhân OEE 0,75", "html": "<p class=\"mt-calc\">= <b>121 500<\/b> hộp<\/p>", "ask": {"q": "Năng lực thực tế?", "o": ["162 000", "121 500", "135 000"], "a": 1}}]}, {"label": "Ví dụ: Đơn 130 000 hộp", "note": "Thiếu bao nhiêu, cần tăng ca bao lâu?", "steps": [{"t": "Thiếu", "html": "<p class=\"mt-calc\">130 000 − 121 500 = 8 500 hộp<\/p>"}, {"t": "Giờ tăng ca", "html": "<p class=\"mt-calc\">8 500 / (1 800 × 0,75) ≈ <b>6,3 giờ<\/b><\/p>", "ask": {"q": "Cần khoảng bao nhiêu giờ tăng ca?", "o": ["4,7", "6,3", "8,5"], "a": 1}}]}, {"label": "Ví dụ: Yêu cầu nhân lực", "note": "Chỉ người có chứng chỉ mới vận hành M1.", "steps": [{"t": "Công đoạn 10 cần chứng chỉ M1", "html": "<p class=\"mt-calc\">Ca 2 chỉ có 1 người có chứng chỉ<\/p>"}, {"t": "Người đó nghỉ phép", "html": "<p class=\"mt-calc\">Năng lực ca 2 của L1 = 0 dù máy vẫn tốt<\/p>", "say": "<p>Năng lực gồm cả người, không chỉ máy.<\/p>"}]}, {"label": "Bẫy: Kế hoạch bằng năng lực lý thuyết", "note": "Bỏ qua tổn thất thực tế.", "steps": [{"t": "Nhận đơn 160 000 hộp", "html": "<p class=\"mt-calc\">Vì năng lực lý thuyết 162 000<\/p>"}, {"t": "Thực tế làm được ~121 500", "html": "<p class=\"mt-calc\">Trễ khoảng 38 500 hộp<\/p>"}]}, {"label": "Lỗi: Dùng chu kỳ máy nhanh nhất", "note": "Năng lực là của nút cổ chai.", "steps": [{"t": "Tính bằng M3 (1,5 s)", "html": "<p class=\"mt-calc\">2 400 hộp/giờ<\/p>"}, {"t": "Sửa: dùng M1 (2,0 s)", "html": "<p class=\"mt-calc\">1 800 hộp/giờ<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l19"),"l19",[{"kind": "num", "t": "Năng lực", "d": "<p>Trả lời bằng một số (giờ làm tròn 1 chữ số).<\/p>", "items": [{"q": "80 giờ kế hoạch, 1 800 hộp/giờ. Năng lực lý thuyết?", "a": 144000, "unit": "hộp"}, {"q": "OEE 0,8. Năng lực thực tế?", "a": 115200, "unit": "hộp"}, {"q": "Đơn 120 000. Cần thêm bao nhiêu giờ (năng lực thực tế mỗi giờ 1 440)?", "a": 3.3, "unit": "giờ", "tol": 0.05}], "hints": ["Lý thuyết = giờ × năng lực giờ.", "Thực tế = lý thuyết × OEE.", "Giờ thêm = thiếu / năng lực thực mỗi giờ."], "why": "80 × 1 800 = 144 000; × 0,8 = 115 200; thiếu 4 800 / 1 440 ≈ 3,3 giờ."}, {"kind": "pick", "t": "Định nghĩa sản phẩm hay năng lực?", "d": "<p>Thông tin này thuộc khái niệm nào?<\/p>", "cats": ["Định nghĩa sản phẩm", "Năng lực sản xuất"], "items": [{"q": "SP-07 cần 0,500 kg hạt mỗi hộp", "a": 0}, {"q": "L1 có 90 giờ kế hoạch tuần này", "a": 1}, {"q": "Công đoạn 10 cần người có chứng chỉ M1", "a": 0}, {"q": "Ca 2 có 1 người có chứng chỉ M1", "a": 1}], "hints": ["Định nghĩa: sản phẩm cần gì.", "Năng lực: nhà máy có gì."], "why": "Yêu cầu của sản phẩm thuộc định nghĩa; tài nguyên hiện có thuộc năng lực."}, {"kind": "order", "t": "Kiểm tra kịp đơn", "d": "<p>Sắp xếp.<\/p>", "items": ["Lấy năng lực giờ của nút cổ chai", "Nhân giờ kế hoạch", "Nhân OEE trung bình đã đo", "So với số lượng đơn", "Tính giờ tăng ca nếu thiếu"], "hints": ["Bắt đầu từ năng lực giờ.", "So sánh sau khi đã nhân OEE."], "why": "Năng lực giờ → × giờ → × OEE → so đơn → tăng ca."}]);
mesSim(document.getElementById("sim-l19"),Object.assign({id:"l19"},{kind:"calc",title:"So nhu cầu với năng lực của L1",
 inputs:[{k:"h",l:"Giờ kế hoạch tuần",min:60,max:150,step:5,v:90,u:"giờ"},{k:"cyc",l:"Chu kỳ nút cổ chai",min:1.5,max:2.5,step:0.1,v:2,u:"s"},{k:"oee",l:"OEE trung bình đã đo",min:0.5,max:0.95,step:0.01,v:0.75},{k:"dem",l:"Nhu cầu tuần",min:80000,max:200000,step:5000,v:130000,u:"hộp"}],
 outputs:[{k:"lt",l:"Năng lực lý thuyết",f:V=>V.h*3600/V.cyc,fmt:v=>mesFmt(v)+" hộp"},{k:"tt",l:"Năng lực thực tế (× OEE)",f:(V,R)=>R.lt*V.oee,fmt:v=>mesFmt(v)+" hộp"},
  {k:"gap",l:"Thiếu (−) / dư",big:1,f:(V,R)=>R.tt-V.dem,fmt:v=>(v<0?"thiếu ":"dư ")+mesFmt(Math.abs(v))+" hộp",cls:v=>v<0?"er":"ok"},
  {k:"ot",l:"Giờ tăng ca cần",f:(V,R)=>R.gap<0?-R.gap/(3600/V.cyc*V.oee):0,fmt:v=>mesFmt(v,1)+" giờ"}],
 bars:(V,R)=>[["Lý thuyết",R.lt,"m"],["Thực tế",R.tt,"a"],["Nhu cầu",V.dem,R.tt<V.dem?"er":"ok"]].map(x=>[x[0],x[1],x[2],mesFmt(x[1])]),
 tasks:[{t:"Với số liệu bài, thiếu bao nhiêu hộp và cần bao nhiêu giờ tăng ca?",ok:"Thiếu 8 500 hộp, khoảng 6,3 giờ tăng ca.",check:s=>s.V.dem===130000&&s.V.oee===0.75&&s.V.h===90},
  {t:"Nếu lập kế hoạch bằng năng lực lý thuyết (OEE = 0,95), kết luận đổi thế nào?",ok:"Trông như dư hàng, nhưng thực tế sẽ trễ hạn: luôn dùng OEE đã đo.",check:s=>s.V.oee>=0.95&&s.R.gap>0},
  {t:"Đặt OEE về 0,75 và tìm số giờ kế hoạch tuần vừa đủ cho 130 000 hộp.",check:s=>Math.abs(s.V.oee-0.75)<1e-9&&s.R.gap>=0&&s.V.h<=100}]}));

